"""Generate a read-only MM-SafetyBench original-model inventory notebook."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'notebooks' / 'mm_safetybench_original_models_preflight.ipynb'
models = [
    ('LLaVA', 'https://github.com/haotian-liu/LLaVA', 'LLaVA-1.5-7B and 13B in paper Table 3; checkpoint revision and exact settings unverified.'),
    ('IDEFICS', 'https://huggingface.co/docs/transformers/model_doc/idefics', 'Official Transformers documentation; exact paper checkpoint and T4 fit unverified.'),
    ('InstructBLIP', 'https://github.com/salesforce/LAVIS/tree/main/projects/instructblip', 'Official LAVIS project; paper checkpoint, setup and T4 fit unverified.'),
    ('MiniGPT-4', 'https://github.com/Vision-CAIR/MiniGPT-4', 'Official project; base model and aligned checkpoint requirements require review.'),
    ('mPLUG-Owl', 'https://github.com/X-PLUG/mPLUG-Owl', 'Use original Owl, not a later generation; exact paper checkpoint unverified.'),
    ('Otter', 'https://github.com/EvolvingLMMs-Lab/Otter', 'Original multimodal Otter; checkpoint and processor unverified.'),
    ('LLaMA-Adapter V2', 'https://github.com/OpenGVLab/LLaMA-Adapter', 'Official repository; base weights and adapter combination need verification.'),
    ('CogVLM', 'https://github.com/zai-org/CogVLM', 'Use original CogVLM; checkpoint, memory and access unverified.'),
    ('MiniGPT-5', 'https://github.com/UCSB-AI/MiniGPT-5', 'Official README describes base and staged checkpoints; exact paper setup unverified.'),
    ('MiniGPT-v2', 'https://github.com/Vision-CAIR/MiniGPT-4', 'Shared official repository; use v2-specific model and configuration.'),
    ('Shikra', 'https://github.com/shikras/shikra', 'Official project; checkpoint, prompt and access unverified.'),
    ('Qwen-VL', 'https://github.com/QwenLM/Qwen-VL', 'Original Qwen-VL; not the Qwen2.5-VL model in our exploratory run.'),
]
def md(text):
    return {'cell_type': 'markdown', 'metadata': {}, 'source': text.splitlines(keepends=True)}
def code(text):
    return {'cell_type': 'code', 'execution_count': None, 'metadata': {}, 'outputs': [], 'source': text.splitlines(keepends=True)}
cells = [md('''# MM-SafetyBench original model families — source audit and preparation\n\nThis is a **preparation notebook**, not an implemented or validated 12-model runner. It does not install packages, download weights, make model calls, or score responses. The separate Qwen2.5-VL experiment used one newer model, not the paper's twelve families.\n\nPaper: [MM-SafetyBench v5, Sections 3.2–3.3 and 4.1](https://arxiv.org/html/2311.17600v5). Author code: [MM-SafetyBench repository](https://github.com/isXinLiu/MM-SafetyBench).\n\n**Marking convention:** `*** -------` in a heading marks our implementation, interpretation, or operational guidance; it is not the benchmark authors' code. Model project links lead to the model authors' upstream projects, which are separate from the MM-SafetyBench release.\n\nDo not overwrite the prior notebook or private response files. Exact checkpoint versions, model interfaces, author inference settings, TYPO mapping, judge deployment and T4 compatibility remain unverified. No scientific run or paid calls are launched by this notebook.\n'''),
md('''## Paper target-model inventory\n\nLinks point to upstream model project code or official documentation, not necessarily the exact historical revision. The benchmark authors do not provide a complete inference driver for all models. The links have not been validated for every checkpoint, license or current runtime.\n''')]
for name, url, note in models:
    cells.append(md(f'### *** ------- {name}: our source notes\n\n[Official project or documentation]({url})  \n{note}\n\n**Audit before loading:** exact checkpoint and revision; model-specific loader; image processing; conversation template; dependency versions; access/license; precision and actual GPU memory. Record source and unknowns; do not assume defaults reproduce the paper.\n'))
cells += [md('''## *** ------- Our proposed workflow\n\n1. Preserve the unchanged benchmark repository and separately hosted image archive. Verify image-to-question mapping and compare the README and paper typography discrepancy.\n2. Choose one paper result and recover the corresponding original checkpoint and settings from original sources.\n3. Review that model author's inference example and prepare a separate, labeled adapter; perform a harmless compatibility test only after the required plan and authorization.\n4. Repeat the process for the other families. Run models sequentially; restarting the runtime between incompatible dependency stacks may be required. Do not delete an existing runtime.\n5. Evaluate saved responses separately using the author rubric. The Azure GPT-4 service call is not implemented in the released evaluator.\n\nReport completed, failed and missing cases; model response coverage is not attack success rate. Preserve outputs and an aggregate snapshot before changing run configuration.\n'''),
md('''## *** ------- Our integration: read-only environment check\n\nThe following cell is our diagnostic code, not code released by the paper authors. It only prints the Python version and whether a GPU is visible. It does not mount Drive or run a model.\n'''),
code('''import sys\nprint("Python:", sys.version.split()[0])\ntry:\n    import torch\n    print("Torch:", torch.__version__)\n    print("GPU:", torch.cuda.get_device_name(0) if torch.cuda.is_available() else "not available")\nexcept ImportError:\n    print("Torch: not installed")\n'''),
md('''## *** ------- Our integration: inspect the unchanged author source ZIP\n\nOur read-only audit checks the saved ZIP's integrity, revision marker, and presence of the relevant released files. It does not extract, modify, or publish benchmark inputs. Run after mounting your own Drive. Failure is a stop signal, not evidence that the model or dataset is invalid.\n'''),
code('''from pathlib import Path\nimport hashlib, zipfile\n\nAUTHOR_ZIP = Path('/content/drive/MyDrive/MM_SafetyBench_Full_20261102_PRIVATE/MM-SafetyBench-main.zip')\nEXPECTED_REVISION = 'b80eedea3db312c09ded2082813390f68e750ef3'\nEXPECTED_SHA256 = '801a891382a06b7c3b29083dd3844b6da6a3e0ef31d3dfdd9086e30b323f322b'\nif not AUTHOR_ZIP.is_file():\n    print('Source ZIP unavailable: mount Drive or set AUTHOR_ZIP to your verified copy.')\nelse:\n    digest = hashlib.sha256(AUTHOR_ZIP.read_bytes()).hexdigest()\n    with zipfile.ZipFile(AUTHOR_ZIP) as archive:\n        names = set(archive.namelist())\n        needed = ['README.md', 'TinyVersion_ID_List.json', 'evaluation.py', 'creation/1_extract_key_words.py', 'creation/2_img_process.py']\n        checks = {item: any(name.endswith('/' + item) for name in names) for item in needed}\n        questions = [name for name in names if '/data/processed_questions/' in name and name.endswith('.json')]\n        print('ZIP hash matches preserved source:', digest == EXPECTED_SHA256)\n        print('Revision marker matches:', archive.comment.decode('ascii', errors='replace') == EXPECTED_REVISION)\n        print('ZIP integrity OK:', archive.testzip() is None)\n        print('Required source files present:', all(checks.values()))\n        print('Processed scenario JSON files:', len(questions))\n        print('Source file checks:', checks)\n'''),
md('''## *** ------- Our integration: audit released question and image pair counts\n\nThis is our read-only code. It compares author question IDs against the separately downloaded author image ZIP and reports aggregate counts only. The image ZIP path is not yet known to persist in Drive: provide its actual location. This check does not establish that the README TYPO mapping matches the paper or decode every image.\n'''),
code('''import json, zipfile\nfrom collections import Counter\n\nIMAGE_ZIP = Path('/content/drive/MyDrive/MM_SafetyBench_Full_20261102_PRIVATE/MM-SafetyBench(imgs).zip')\nif not AUTHOR_ZIP.is_file() or not IMAGE_ZIP.is_file():\n    print('Question or image archive missing. Set IMAGE_ZIP to the verified author archive; no files changed.')\nelse:\n    with zipfile.ZipFile(AUTHOR_ZIP) as source, zipfile.ZipFile(IMAGE_ZIP) as images:\n        image_names = images.namelist()\n        question_names = [n for n in source.namelist() if '/data/processed_questions/' in n and n.endswith('.json')]\n        counts = Counter()\n        for name in question_names:\n            scenario = Path(name).stem\n            for item in json.loads(source.read(name)):\n                for variant in ('SD', 'TYPO', 'SD_TYPO'):\n                    suffix = f'/{scenario}/{variant}/{item}.jpg'\n                    matches = sum(entry.endswith(suffix) for entry in image_names)\n                    counts['planned'] += 1\n                    counts['exactly_one' if matches == 1 else 'missing' if matches == 0 else 'ambiguous'] += 1\n        print('Scenario files:', len(question_names))\n        print('Pair counts:', dict(counts))\n        print('Image ZIP integrity OK:', images.testzip() is None)\n'''),
md('''## *** ------- Our proposed next step\n\nStart with LLaVA-1.5-7B as a candidate because Table 3 reports it and the upstream project releases a checkpoint. First verify the exact revision, image processing, generation settings, input mapping and scoring protocol. Do not call the checkpoint an exact match until those are established.\n''')]
nb = {'cells': cells, 'metadata': {'colab': {'name': 'MM-SafetyBench original models inventory'}, 'kernelspec': {'display_name': 'Python 3', 'language': 'python', 'name': 'python3'}, 'language_info': {'name': 'python'}}, 'nbformat': 4, 'nbformat_minor': 5}
